#!/bin/sh
# sc3mods_patch.sh - Linux / macOS version of sc3mods_patch.ps1 (POSIX sh, no Python, no PowerShell).
#
# The sc3kre mods are loaded by Apps/sc3mods.dll. For the loader to map that DLL on a normal game start, SC3U.exe must
# import it. This script adds one import descriptor for sc3mods.dll to Apps/SC3U.exe, the same single edit
# sc3mods_patch.ps1 makes. It changes no game code. The result is byte-identical to the .ps1 output (checked by SHA-256
# before the exe is replaced). The game exe is never shipped: you run this on your own install.
#
# Usage (from the game's Apps folder, or give the folder):
#   sh sc3mods_patch.sh              patch Apps/SC3U.exe (keeps Apps/SC3U.exe.orig, the same backup the .ps1 keeps)
#   sh sc3mods_patch.sh --restore    put the stock SC3U.exe back from the backup
#   sh sc3mods_patch.sh --apps DIR   the folder that holds SC3U.exe
#
# Accepted exes: stock 2.0.0.3, stock 2.0.949 (GOG / Steam), a signed copy of either (signature cut off), or an exe this
# script or the .ps1 already patched. Anything else is refused and nothing is changed.
#
# Tools used: sh, dd, od, wc, cp, mv, rm, cut, tr, grep, printf, and sha256sum (Linux) or shasum -a 256 (macOS).
#
# The patch data between BEGIN GENERATED and END GENERATED is written by re/tools/lxpatch_gen.py from the real
# .ps1 output. Do not edit it by hand: run the generator again if the .ps1 changes.

SECNAME_HEX='2e 73 63 33 6d 6f 64 00'   # ".sc3mod" + NUL, the section name the patch adds

die() { echo "ERROR: $*" >&2; exit 1; }

# ---- helpers -----------------------------------------------------------------------------------------------------
if command -v sha256sum >/dev/null 2>&1; then
    sha256() { sha256sum < "$1" | cut -d' ' -f1; }
elif command -v shasum >/dev/null 2>&1; then
    sha256() { shasum -a 256 < "$1" | cut -d' ' -f1; }
else
    die "neither sha256sum nor shasum found."
fi

fsize() { wc -c < "$1" | tr -d ' '; }

# little-endian unsigned integer of N bytes at offset: rdle FILE OFFSET N
rdle() {
    set -- "$1" "$2" "$3" $(od -An -tu1 -j "$2" -N "$3" "$1")
    _f=$1; _n=$3; shift 3
    _v=0; _m=1
    while [ "$_n" -gt 0 ]; do
        _v=$((_v + $1 * _m)); _m=$((_m * 256)); shift; _n=$((_n - 1))
    done
    echo "$_v"
}

hexbytes() { od -An -tx1 -j "$2" -N "$3" "$1" | tr -s ' \n' ' ' | sed 's/^ //; s/ $//'; }

# zero N bytes at OFFSET in FILE in place: zero_at FILE OFFSET N
zero_at() {
    _z=''; _i=0
    while [ "$_i" -lt "$3" ]; do _z="$_z\\000"; _i=$((_i + 1)); done
    printf "$_z" | dd of="$1" bs=1 seek="$2" conv=notrunc 2>/dev/null
}

# PE header facts of FILE -> LFANEW OPT NSEC SOH (dies when it is not a PE32)
pe_info() {
    [ "$(fsize "$1")" -ge 1024 ] || die "$1 is too small to be an exe."
    LFANEW=$(rdle "$1" 60 4)
    [ "$(hexbytes "$1" "$LFANEW" 4)" = "50 45 00 00" ] || die "$1 is not a PE (no PE signature)."
    OPT=$((LFANEW + 24))
    [ "$(rdle "$1" "$OPT" 2)" -eq 267 ] || die "$1 is not PE32 (x86)."
    NSEC=$(rdle "$1" $((LFANEW + 6)) 2)
    SOH=$(rdle "$1" $((LFANEW + 20)) 2)
}

has_section() {   # FILE: succeeds when the .sc3mod section is in the section table
    pe_info "$1"
    _t=$((LFANEW + 24 + SOH)); _i=0
    while [ "$_i" -lt "$NSEC" ]; do
        [ "$(hexbytes "$1" $((_t + _i * 40)) 8)" = "$SECNAME_HEX" ] && return 0
        _i=$((_i + 1))
    done
    return 1
}

# normalise SRC into DST: signature at the end cut off, security directory and PE checksum zeroed
normalise() {
    pe_info "$1"
    _size=$(fsize "$1")
    _so=$(rdle "$1" $((OPT + 128)) 4); _ss=$(rdle "$1" $((OPT + 132)) 4)
    if [ "$_so" -gt 0 ] && [ "$_ss" -gt 0 ] && [ $((_so + _ss)) -ge $((_size - 8)) ] && [ "$_so" -le "$_size" ]; then
        dd if="$1" of="$2" bs="$_so" count=1 2>/dev/null
    else
        cp "$1" "$2"
    fi
    zero_at "$2" $((OPT + 128)) 8
    zero_at "$2" $((OPT + 64)) 4
}

# identify FILE -> BUILD ('2.0.949', '2.0.949 (signed copy)' or empty), RAWSHA, NORMSHA, ID, PATCHED_SHA
identify() {
    BUILD=''; ID=''; PATCHED_SHA=''
    RAWSHA=$(sha256 "$1")
    normalise "$1" "$TMPN" || die "could not read $1."
    NORMSHA=$(sha256 "$TMPN")
    rm -f "$TMPN"
    if build_info "$RAWSHA"; then return 0; fi
    if build_info "$NORMSHA"; then BUILD="$BUILD (signed copy)"; return 0; fi
    BUILD=''; ID=''; PATCHED_SHA=''
    return 0
}

show_report() {
    pe_info "$1"
    echo "  size $(fsize "$1"), timestamp $(rdle "$1" $((LFANEW + 8)) 4), checksum $(rdle "$1" $((OPT + 64)) 4)," \
         "security dir at $(rdle "$1" $((OPT + 128)) 4) size $(rdle "$1" $((OPT + 132)) 4)  (decimal)"
    normalise "$1" "$TMPN"; echo "  normalised SHA-256 $(sha256 "$TMPN")"; rm -f "$TMPN"
    _t=$((LFANEW + 24 + SOH)); _i=0
    while [ "$_i" -lt "$NSEC" ]; do
        _o=$((_t + _i * 40))
        echo "  section $(dd if="$1" bs=1 skip="$_o" count=8 2>/dev/null | tr -d '\000') VA $(rdle "$1" $((_o + 12)) 4)" \
             "raw $(rdle "$1" $((_o + 20)) 4) size $(rdle "$1" $((_o + 16)) 4)  (decimal)"
        _i=$((_i + 1))
    done
}

