# END GENERATED

# ---- arguments ---------------------------------------------------------------------------------------------------
RESTORE=0; APPS=''
while [ $# -gt 0 ]; do
    case "$1" in
        --restore|-r|-Restore) RESTORE=1 ;;
        --apps|-a)  [ $# -ge 2 ] || die "$1 needs a folder."; APPS=$2; shift ;;
        -h|--help)  sed -n '2,/^$/p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        -*)         die "unknown option $1 (try --help)." ;;
        *)          APPS=$1 ;;
    esac
    shift
done

HERE=$(cd "$(dirname "$0")" 2>/dev/null && pwd)
if [ -z "$APPS" ]; then
    if   [ -f "$HERE/SC3U.exe" ];      then APPS=$HERE
    elif [ -f "$HERE/Apps/SC3U.exe" ]; then APPS=$HERE/Apps
    elif [ -f "./SC3U.exe" ];          then APPS=.
    else APPS=$HERE; fi
fi
EXE=$APPS/SC3U.exe
BAK=$APPS/SC3U.exe.orig
TMPN=$APPS/SC3U.exe.norm_tmp
TMPP=$APPS/SC3U.exe.patch_tmp
trap 'rm -f "$TMPN" "$TMPP"' EXIT HUP INT TERM
[ -f "$EXE" ] || die "SC3U.exe not found in $APPS. Pass --apps <folder>."

# ---- restore -----------------------------------------------------------------------------------------------------
if [ "$RESTORE" -eq 1 ]; then
    [ -f "$BAK" ] || die "No backup SC3U.exe.orig in $APPS. Nothing to restore."
    identify "$BAK"
    [ -n "$BUILD" ] || die "Backup SC3U.exe.orig ($RAWSHA) is not a known stock build. Refusing to restore it."
    identify "$EXE"
    if [ -n "$BUILD" ]; then
        echo "SC3U.exe is already stock. Nothing to restore."
    else
        cp "$BAK" "$TMPP" && mv -f "$TMPP" "$EXE" || die "could not write $EXE."
        echo "Restored stock SC3U.exe from the backup."
    fi
    rm -f "$BAK"
    echo "Removed the backup. The mods will not load now (stock game)."
    echo "To load the mods again, run this script with no arguments."
    exit 0
fi

# ---- patch -------------------------------------------------------------------------------------------------------
if has_section "$EXE"; then
    echo "SC3U.exe already imports sc3mods.dll (section .sc3mod present). Nothing to do."
    [ -f "$BAK" ] || echo "  note: no SC3U.exe.orig backup is present; --restore will not work until you reinstall stock."
    [ -f "$APPS/sc3mods.dll" ] || echo "  WARNING: sc3mods.dll is missing from $APPS. The game will fail to start until it is there." >&2
    exit 0
fi

identify "$EXE"
if [ -z "$BUILD" ]; then
    echo "SC3U.exe is not a build this script knows. Details for a bug report:" >&2
    show_report "$EXE" >&2
    die "SC3U.exe hash $RAWSHA is neither a known stock build (GOG 2.0.0.3, GOG/Steam 2.0.949, or a signed copy of one) nor an exe this script patched. Refusing. Please post the lines above in a bug report."
fi
HASH=$RAWSHA; CUR_ID=$ID; CUR_PATCHED=$PATCHED_SHA; CUR_BUILD=$BUILD
echo "Stock SC3U.exe build $CUR_BUILD recognised."

if [ ! -f "$BAK" ]; then
    cp "$EXE" "$BAK" || die "could not write the backup."
    echo "Backed up stock SC3U.exe -> SC3U.exe.orig"
else
    identify "$BAK"
    [ -n "$BUILD" ] || die "SC3U.exe.orig exists but is not a known stock build. Move it aside and run again."
    if [ "$RAWSHA" != "$HASH" ]; then
        _bb=$BUILD
        cp "$EXE" "$BAK" || die "could not write the backup."
        echo "Replaced SC3U.exe.orig (build $_bb) with this stock SC3U.exe (build $CUR_BUILD)."
    fi
fi

# the patch is applied to the normalised exe (a signed copy loses its signature here, SC3U.exe.orig keeps it)
normalise "$EXE" "$TMPP" || die "could not read $EXE."
case "$CUR_BUILD" in *"signed copy"*)
    echo "  removed the file signature from the copy being patched (SC3U.exe.orig keeps it)." ;;
esac
apply_patch "$CUR_ID" "$TMPP"
[ "$(sha256 "$TMPP")" = "$CUR_PATCHED" ] || die "the patched exe does not match the expected hash. $EXE was NOT changed."
mv -f "$TMPP" "$EXE" || die "could not write $EXE."
echo "Patched SC3U.exe: added import of sc3mods.dll (new section .sc3mod)."
echo "  new SHA-256: $CUR_PATCHED"

# remove a leftover loader from older releases (version.dll beside the exe), only if it is ours
if [ -f "$APPS/version.dll" ]; then
    if grep -aq -e 'sc3modldr ' -e 'sc3mods ' "$APPS/version.dll"; then
        rm -f "$APPS/version.dll"
        echo "  removed the old Apps/version.dll loader (superseded by sc3mods.dll)."
    else
        echo "  note: Apps/version.dll is present but is not ours (left as-is)."
    fi
fi
[ -f "$APPS/sc3mods.dll" ] || echo "  WARNING: sc3mods.dll is not in $APPS yet. Copy it there before starting the game." >&2
echo
echo "Start the game normally (SC3U.exe or your shortcut). To go back to stock: run this with --restore."
exit 0
